import{_ as i,c as l,a as r,b as s,d as t,e as a,w as o,r as c,o as d}from"./app-BxKNaJMq.js";const p="/tero/assets/edit-agent-Bo3pWhCk.png",h="/tero/assets/agent-tests-BOkq9hDB.png",u={},g={class:"hint-container tip"},m={class:"hint-container tip"},f={class:"hint-container tip"},v={class:"hint-container warning"};function b(y,e){const n=c("RouteLink");return d(),l("div",null,[e[34]||(e[34]=r('<h1 id="create-agents" tabindex="-1"><a class="header-anchor" href="#create-agents"><span>Create Agents</span></a></h1><p><img src="'+p+'" alt="Edit Agent"></p><p>If there isn’t an agent that helps with your needs, create one! Creating an agent is simple, and once it works and helps you, share it so your team and the Tero community can benefit too.</p><p>While you create or edit an agent, every change is saved automatically and you can try your changes right away in the chat on the right.</p><h2 id="clone" tabindex="-1"><a class="header-anchor" href="#clone"><span>Clone</span></a></h2><p>One of the easiest ways to create an agent is to clone an existing one. This lets you adapt an agent to your context (project, preferences, way of working), or create similar agents reusing existing ones as templates.</p>',6)),s("p",null,[e[1]||(e[1]=t("You can clone an agent from the agent detail dialog in ",-1)),a(n,{to:"/guide/discover.html"},{default:o(()=>[...e[0]||(e[0]=[t("Explore agents",-1)])]),_:1}),e[2]||(e[2]=t(" or from any chat with that agent.",-1))]),e[35]||(e[35]=s("h2",{id:"basic-info",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#basic-info"},[s("span",null,"Basic Info")])],-1)),e[36]||(e[36]=s("p",null,"When you create an agent, choose a good icon, name, and description. This helps quickly identify it among other agents.",-1)),e[37]||(e[37]=s("p",null,"Names and descriptions are purposely short in Tero to support quick scanning and selection. Think of the user and be succinct so the agent’s purpose is clear.",-1)),s("div",g,[e[6]||(e[6]=s("p",{class:"hint-container-title"},"Description for subagents",-1)),s("p",null,[e[4]||(e[4]=t("If this agent will be used as a ",-1)),a(n,{to:"/guide/tools/subagent.html"},{default:o(()=>[...e[3]||(e[3]=[t("subagent",-1)])]),_:1}),e[5]||(e[5]=t(", the parent uses the description to decide when to delegate. Keep it specific about what the agent is for.",-1))])]),e[38]||(e[38]=r('<div class="hint-container tip"><p class="hint-container-title">Auto-generate</p><p>Tero can auto-generate the name, description, and system prompt from the other fields. If you’ve set some fields, use the magic wand to generate or refine the rest. It’s handy for starting values or quick adjustments.</p></div><h2 id="model" tabindex="-1"><a class="header-anchor" href="#model"><span>Model</span></a></h2><p>Tero supports a growing variety of LLM models you can use as the basis for your agent. The model is like the agent’s brain: it analyzes each user request, plans how to answer using the configured tools, and either generates an answer or invokes tools as needed.</p><p>Available models in your Tero instance depend on how it’s configured. Currently Tero supports models from OpenAI (GPT), Azure OpenAI (GPT), AWS Bedrock (Claude), and Google (Gemini). The community continues to expand this list.</p><div class="hint-container tip"><p class="hint-container-title">Cheaper &amp; faster first</p><p>When creating an agent, start with cheaper and faster models. They’re easier to use and help you, and others, avoid unnecessary budget spend (in general more powerful = more expensive).</p></div><div class="hint-container tip"><p class="hint-container-title">Experiment</p><p>Different models excel at different tasks (e.g., Claude often shines for code; GPT can be great for brainstorming or writing). Experiment, and don’t assume a new version of a model behaves like the previous one.</p></div><p>Depending on the model type, you may also set Temperature or Reasoning level.</p><h3 id="temperature" tabindex="-1"><a class="header-anchor" href="#temperature"><span>Temperature</span></a></h3><p>Temperature controls how much the agent’s answers vary. For more creative outputs (e.g., brainstorming), choose Creative. For more consistent, precise answers with less variation, choose Precise. Use Neutral for a balanced behavior.</p><h3 id="reasoning-level" tabindex="-1"><a class="header-anchor" href="#reasoning-level"><span>Reasoning Level</span></a></h3><p>Reasoning level defines how much the agent analyzes before answering. More reasoning usually means better results but slower responses. Use High for complex tasks, Low for simple tasks, and Medium for relatively simple ones.</p><h2 id="instructions" tabindex="-1"><a class="header-anchor" href="#instructions"><span>Instructions</span></a></h2><p>The instructions (aka system prompt) define how your agent responds to user requests. A good system prompt usually includes a role the agent should assume, the main tasks it solves, formatting expectations for answers, and optionally examples of inputs and outputs.</p><div class="hint-container tip"><p class="hint-container-title">Short and simple</p><p>Prefer short, simple prompts. The bigger the prompt, the harder it is to follow by the agent and for you to maintain.</p></div><div class="hint-container tip"><p class="hint-container-title">Agent to tune system prompt</p><p>Use an agent to help you improve your system prompt. You can use the <a href="https://github.com/abstracta/tero-agents/blob/main/en/agents-from-scratch/agent.md" target="_blank" rel="noopener noreferrer">Agents from Scratch</a> agent if you need help to start from scratch.</p></div>',15)),s("div",m,[e[12]||(e[12]=s("p",{class:"hint-container-title"},"Divide & Conquer",-1)),e[13]||(e[13]=s("p",null,"Avoid “do everything” agents. Focus each agent on a specific task and create multiple agents for different needs. It keeps instructions short, answers better, reduces budget by limiting context, and makes it easier for users to discover the right agent.",-1)),s("p",null,[e[8]||(e[8]=t("To combine specialists into one workflow, switch the orchestrator to ",-1)),e[9]||(e[9]=s("a",{href:"#agent-mode"},"Advanced",-1)),e[10]||(e[10]=t(" mode and add the ",-1)),a(n,{to:"/guide/tools/subagent.html"},{default:o(()=>[...e[7]||(e[7]=[t("Subagent",-1)])]),_:1}),e[11]||(e[11]=t(" tool.",-1))])]),s("div",f,[e[17]||(e[17]=s("p",{class:"hint-container-title"},"Optimize",-1)),s("p",null,[e[15]||(e[15]=t("Start simple, then optimize. Review the ",-1)),a(n,{to:"/guide/chat.html#thought-process"},{default:o(()=>[...e[14]||(e[14]=[t("Thought Process",-1)])]),_:1}),e[16]||(e[16]=t(" to see how the agent solves requests and add step-by-step guidance to the prompt for recurring tasks. This makes answers faster, more predictable, and reduces budget usage. With detailed instructions, you can often use cheaper & faster models too.",-1))])]),e[39]||(e[39]=r(`<div class="hint-container tip"><p class="hint-container-title">Markdown</p><p>Ask the agent to format answers in Markdown. You’ll get cleaner results (headings, lists, tables, code blocks, etc.).</p></div><div class="hint-container tip"><p class="hint-container-title">PlantUML</p><p>If you need UML or general diagrams, ask the agent to use <a href="https://plantuml.com/" target="_blank" rel="noopener noreferrer">PlantUML</a>.</p><p>When doing so, instruct the agent not to wrap diagrams in code blocks so they render properly. Add something like the following to the agent&#39;s system prompt:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">When generating PlantUML diagrams, do not wrap them in code blocks. Output the raw diagram text starting directly with @startuml.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Example — this generates only the text of the diagram:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">\`\`\`plantuml</span>
<span class="line">@startuml</span>
<span class="line">[User] --&gt; [App]</span>
<span class="line">@enduml</span>
<span class="line">\`\`\`</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>And this renders a diagram image:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">@startuml</span>
<span class="line">[User] --&gt; [App]</span>
<span class="line">@enduml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><div class="hint-container tip"><p class="hint-container-title">ECharts</p><p>You can also ask the agent to present information using charts with <a href="https://echarts.apache.org/en/index.html" target="_blank" rel="noopener noreferrer">ECharts</a>.</p></div><h2 id="conversation-starters" tabindex="-1"><a class="header-anchor" href="#conversation-starters"><span>Conversation Starters</span></a></h2>`,4)),s("p",null,[e[20]||(e[20]=t("When you create an agent, consider adding ",-1)),a(n,{to:"/guide/chat.html#conversation-starters"},{default:o(()=>[...e[18]||(e[18]=[t("Conversation starters",-1)])]),_:1}),e[21]||(e[21]=t(". They help new users understand what the agent can do and get going quickly. Like any other prompt, they can use ",-1)),a(n,{to:"/guide/chat.html#variables"},{default:o(()=>[...e[19]||(e[19]=[t("variables",-1)])]),_:1}),e[22]||(e[22]=t(" to ask for the details you need.",-1))]),e[40]||(e[40]=r('<h2 id="tools" tabindex="-1"><a class="header-anchor" href="#tools"><span>Tools</span></a></h2><p>Tools extend what your agents can do. Below is the list of currently supported tools. Expect it to grow as the community contributes new ones.</p><div class="hint-container tip"><p class="hint-container-title">Keep it lean</p><p>Enable only the tools your agent truly needs. Fewer tools makes the agent faster, cheaper, and more predictable.</p></div><h3 id="docs" tabindex="-1"><a class="header-anchor" href="#docs"><span>Docs</span></a></h3><p>Upload files to your agent so it can use their content when answering questions. The agent searches the uploaded files using semantic similarity and grounds its responses in what the documents actually say, citing the source files.</p><p>This is useful for agents that need to reason over technical documentation, test plans, specifications, runbooks, or any domain-specific knowledge that isn&#39;t in the model&#39;s training data.</p><p>The agent can:</p><ul><li><strong>Answer questions</strong> from uploaded documents using semantic search across all files</li><li><strong>Cite sources</strong> — responses reference the specific file sections they were drawn from</li><li><strong>Reason across multiple files</strong> — the agent considers all uploaded files together when answering</li></ul><p>Supported file types include PDF, plain text, Markdown, and common document formats.</p><div class="hint-container tip"><p class="hint-container-title">Basic vs Advanced PDF processing</p><p><strong>Basic</strong> processing is faster and works well for most PDFs. <strong>Advanced</strong> processing (when available) handles complex PDFs with tables, multi-column layouts, and embedded images more accurately, but it costs more and takes longer.</p><p>Use Advanced only when the agent consistently misses or misreads content from your PDFs.</p></div><div class="hint-container tip"><p class="hint-container-title">Verify answers</p><p><strong>Verify answers</strong> is on by default. When enabled, each answer is checked against the uploaded files and source links are added, so the response stays grounded in the documents instead of invented facts. This extra pass takes longer and uses more budget.</p><p>Turn it off for faster, cheaper responses. Stronger models hallucinate less, so verification matters most with smaller models or when you need cited sources.</p></div><h3 id="web" tabindex="-1"><a class="header-anchor" href="#web"><span>Web</span></a></h3><p>Search the web and extract text content from public URLs. The agent can look up current information beyond its training data or read specific pages as part of answering a request.</p><p>The agent can:</p><ul><li><strong>Search</strong> — query the web and retrieve a ranked list of relevant results with snippets</li><li><strong>Extract</strong> — read the full text content of public URLs, including documentation sites, blog posts, changelogs, and issue trackers</li></ul><p>This tool requires no configuration by the agent creator. It is available when a Tero admin has configured a web search API key (Tavily or Google Custom Search) for the instance.</p><div class="hint-container tip"><p class="hint-container-title">Search vs Extract</p><p>The agent uses <strong>search</strong> to find relevant pages for a query, and <strong>extract</strong> to read the full content of a specific URL. You can ask the agent to visit a URL directly, or let it search and pick the best result.</p></div><h3 id="browser" tabindex="-1"><a class="header-anchor" href="#browser"><span>Browser</span></a></h3><p>Automate real browser interactions using Playwright. Unlike the Web tool which only reads static content, the Browser tool can interact with live web pages — useful for apps that require login, dynamic content, or multi-step navigation.</p><p>The agent can:</p><ul><li><strong>Navigate</strong> — open URLs, follow links, handle redirects and page transitions</li><li><strong>Interact</strong> — click buttons, fill forms, select dropdowns, check checkboxes, upload files</li><li><strong>Read</strong> — extract text, read table data, capture the current state of dynamic pages</li><li><strong>Screenshot</strong> — take screenshots to capture the current state of a page</li><li><strong>Wait</strong> — wait for elements to appear or conditions to be met before acting</li></ul><p>This tool requires no configuration by the agent creator.</p><div class="hint-container warning"><p class="hint-container-title">Concurrent browser sessions</p><p>Tero currently only supports 1 active browser session at a time. If multiple users try to use it at the same time they may get a notification about this.</p></div><h3 id="subagent" tabindex="-1"><a class="header-anchor" href="#subagent"><span>Subagent</span></a></h3><p>Delegate parts of a request to another Tero agent. Use this to keep each agent focused on a specialty — for example an orchestrator that routes work to a researcher, a writer, and a reviewer — instead of packing every skill into one prompt.</p><p>The parent agent decides when to delegate. Each subagent runs with its own model, instructions, and tools, then returns a result the parent can use to continue. If a subagent is also Advanced and has its own subagents, it can delegate further.</p><div class="hint-container warning"><p class="hint-container-title">Advanced mode only</p><p>Subagents can only be configured on <strong>Advanced</strong> agents. Switching the parent back to Basic removes the configured subagents.</p></div><h4 id="setup" tabindex="-1"><a class="header-anchor" href="#setup"><span>Setup</span></a></h4><ol><li>Set <strong>Agent mode</strong> to Advanced in the agent&#39;s advanced settings.</li><li>Add the <strong>Subagent</strong> tool.</li><li>Select the agent to delegate to. You can search by name.</li></ol><p>The selected agent&#39;s <strong>description</strong> is what the parent uses to decide when to delegate, so keep it specific about what that agent is for.</p><div class="hint-container info"><p class="hint-container-title">Who you can select</p><p>You cannot select the agent you are configuring as a subagent of itself. You can select other agents, including ones that already have their own subagents.</p><p>If A delegates to B and B delegates back to A, Tero skips the loop at runtime so the chain does not run forever.</p></div><div class="hint-container tip"><p class="hint-container-title">Multiple subagents</p><p>The tool can be added several times to the same agent, once per subagent. Each instance appears with the selected agent&#39;s name.</p></div><h4 id="sharing" tabindex="-1"><a class="header-anchor" href="#sharing"><span>Sharing</span></a></h4><p>Before you share the parent with a team, each subagent must already be shared with that same team, or with the Global team. Private subagents cannot be used by a published orchestrator.</p><div class="hint-container info"><p class="hint-container-title">Thought process</p><p>When the parent delegates, the thought process shows the subagent by name (for example, “Delegating to Researcher”) and the tools that subagent runs.</p></div><div class="hint-container tip"><p class="hint-container-title">Budget</p><p>Each subagent uses its own model, so you can keep a stronger model on the parent and delegate simpler tasks to cheaper, faster ones. Delegated work still counts toward the chat’s budget.</p></div><h3 id="jira" tabindex="-1"><a class="header-anchor" href="#jira"><span>Jira</span></a></h3><p>Manage issues and track project activity in Jira Cloud. The agent can work across the full issue lifecycle and project structure.</p><p>The agent can help with:</p><ul><li><strong>Issues</strong> — create, read, update, and delete issues; add comments and attachments</li><li><strong>Projects</strong> — browse projects and retrieve project details and statuses</li><li><strong>Search</strong> — use JQL (Jira Query Language) to find issues across projects</li><li><strong>Users</strong> — look up user information</li></ul><h4 id="authentication" tabindex="-1"><a class="header-anchor" href="#authentication"><span>Authentication</span></a></h4><p>This tool uses OAuth 2.0 (3LO). You need to create an OAuth app in the Atlassian developer console and provide its credentials.</p><p><strong>Steps to set up:</strong></p><ol><li>Go to <a href="https://developer.atlassian.com" target="_blank" rel="noopener noreferrer">developer.atlassian.com</a> and sign in.</li><li>Open <strong>Developer console</strong> and create a new app.</li><li>In the left menu, go to <strong>Authorization</strong> → click <strong>Configure</strong> next to <strong>OAuth 2.0 (3LO)</strong>.</li><li>Enter the <strong>Callback URL</strong> provided by your Tero instance and save.</li><li>Go to <strong>Permissions</strong> and add the <strong>Jira API</strong>. Enable the scopes you need: <ul><li><code>read:jira-work</code> — read issues, projects, and boards</li><li><code>write:jira-work</code> — create and update issues</li><li><code>read:jira-user</code> — read user information</li></ul></li><li>Copy the <strong>Client ID</strong> and <strong>Client secret</strong> from the app settings.</li></ol><p>Enter the Client ID, Client secret, and selected scopes in the tool configuration. After saving, each user will be prompted to authorize the connection with their Atlassian account.</p><h3 id="azure-devops" tabindex="-1"><a class="header-anchor" href="#azure-devops"><span>Azure DevOps</span></a></h3><p>Browse projects and teams, manage work items, and work with test plans in Azure DevOps Services.</p><p>The agent can help with:</p><ul><li><strong>Projects &amp; teams</strong> — list and read projects and teams, and inspect team membership</li><li><strong>Work items</strong> — search with queries; read, create, update, and delete work items; inspect work item types, fields, states, and relation types; manage field definitions when needed</li><li><strong>Saved queries</strong> — run a saved work item query and get its work items already resolved, optionally narrowed down by an extra condition, with additional fields, and with their related work items</li><li><strong>Traceability</strong> — link work items together (for example user stories and test cases)</li><li><strong>Test plans</strong> — browse and manage test plans, suites, and configurations</li><li><strong>Test cases</strong> — list cases in a suite, add or remove them from suites, find which suites contain a given case, and delete a test case (one at a time)</li><li><strong>Test results</strong> — get the outcome of every test case in a suite and all of its child suites, together with the bugs they are associated with</li></ul><h4 id="authentication-1" tabindex="-1"><a class="header-anchor" href="#authentication-1"><span>Authentication</span></a></h4><p>Microsoft Entra delegated OAuth. Register an app in Entra ID and add <strong>Azure DevOps</strong> delegated permissions matching the scopes you select in Tero.</p><p><strong>Setup:</strong></p><ol><li><a href="https://learn.microsoft.com/en-us/entra/identity-platform/quickstart-register-app" target="_blank" rel="noopener noreferrer">Register an application</a> in Microsoft Entra ID.</li><li>Add a <strong>Web</strong> redirect URI: the callback URL shown in the tool configuration.</li><li>Under <strong>API permissions</strong>, add <strong>Azure DevOps</strong> delegated permissions matching the scopes available in Tero (e.g. <code>vso.profile</code>, <code>vso.project</code>, <code>vso.work</code>, <code>vso.work_write</code>, <code>vso.test</code>, <code>vso.test_write</code>).</li><li>Copy <strong>Application (client) ID</strong>, create a <strong>client secret</strong>, and enter <strong>tenant ID</strong> in Tero.</li></ol><p>Each user authorizes with their Microsoft work account when they first use the tool. Actions run with that user&#39;s Azure DevOps permissions.</p><p>The scopes you select in Tero control what the agent can do:</p><ul><li><strong>Profile (read)</strong> — read the signed-in user&#39;s profile</li><li><strong>Projects and teams (read)</strong> — read projects and teams</li><li><strong>Work items (read)</strong> — read work items</li><li><strong>Work items (write)</strong> — create, update, and delete work items</li><li><strong>Test plans (read)</strong> — read test plans, suites, and cases</li><li><strong>Test plans (write)</strong> — manage test plans, suites, configurations, and suite membership, and delete test cases one at a time</li></ul><p>See <a href="https://learn.microsoft.com/en-us/azure/devops/integrate/get-started/authentication/entra-oauth?view=azure-devops" target="_blank" rel="noopener noreferrer">Entra OAuth for Azure DevOps</a>.</p><h3 id="zephyr" tabindex="-1"><a class="header-anchor" href="#zephyr"><span>Zephyr</span></a></h3><p>Manage test cases, plans, cycles, and executions in Zephyr alongside your Jira projects. The agent can work across test library structure, linkage to Jira issues, planning, and execution tracking.</p><p>When configuring the tool, choose <strong>Zephyr Cloud</strong> or <strong>Zephyr Essential Cloud</strong>. The access token must match the selected product.</p>',60)),s("p",null,[e[24]||(e[24]=t("Zephyr does not require the ",-1)),a(n,{to:"/guide/tools/jira.html"},{default:o(()=>[...e[23]||(e[23]=[t("Jira",-1)])]),_:1}),e[25]||(e[25]=t(" tool, but enabling both is recommended when you need full issue context—reading or updating stories and bugs, JQL search, or backlog work beyond test management and traceability links.",-1))]),e[41]||(e[41]=r(`<p>The agent can help with:</p><ul><li><strong>Test cases</strong> — search test cases by project, status, and name; clone test cases; read and update test cases; folders, labels, and custom fields; steps and scripted tests</li><li><strong>Traceability</strong> — view and create links between test cases and Jira issues</li><li><strong>Test plans &amp; cycles</strong> — create and browse plans and cycles; link cycles to plans when supported by the workflow</li><li><strong>Executions</strong> — create and update executions per cycle and environment; review execution outcomes</li><li><strong>Project context</strong> — list projects, folders, statuses, priorities, and environments relevant to configuring tests</li></ul><h4 id="authentication-2" tabindex="-1"><a class="header-anchor" href="#authentication-2"><span>Authentication</span></a></h4><p>This tool uses a <strong>personal Zephyr API access token</strong>. Each Tero user connects with their own token; Tero stores it per user and reuses it until Zephyr rejects it (for example when the token expires), at which point you are prompted to enter a new one.</p><p>Anything the agent creates or updates in Zephyr is performed as the <strong>Zephyr/Jira user who owns that token</strong>, with that account’s permissions—not as a generic “agent” user.</p><p><strong>Generate an access token</strong></p><ol><li>In Jira/Zephyr, create an API access token for your account (<a href="https://smartbear.portal.swaggerhub.com/zephyr-squad/default/authentication#generate-a-key" target="_blank" rel="noopener noreferrer">Zephyr Essential Cloud</a> or <a href="https://support.smartbear.com/zephyr/docs/en/rest-api/api-access-tokens-management.html" target="_blank" rel="noopener noreferrer">Zephyr Cloud</a>, depending on your product).</li></ol><p><strong>Connect in Tero</strong></p><ol><li><strong>When configuring the agent</strong> — select your <strong>Product</strong>, paste the token in <strong>Access token</strong>, and save. This validates the tool and saves the connection for your Tero user.</li><li><strong>When using the agent</strong> — every other user must enter their own token the first time they chat with that agent (or again after their token stops working). You will see a prompt asking for the token; it is not enough that only the agent creator configured one.</li></ol><h3 id="github" tabindex="-1"><a class="header-anchor" href="#github"><span>GitHub</span></a></h3><p>Search code, manage repositories, review pull requests, and track issues — all through the official GitHub MCP server.</p><p>The agent can help with:</p><ul><li><strong>Issues</strong> — create, read, update, comment on, and label issues</li><li><strong>Pull requests</strong> — create, review, merge, and comment on PRs; request reviews</li><li><strong>Repositories</strong> — browse files and commits, create branches, browse releases and tags</li><li><strong>Users</strong> — look up user profiles and organization members</li><li><strong>Context</strong> — access information about the authenticated user and their teams</li></ul><div class="hint-container info"><p class="hint-container-title">Info</p><p>Only the GitHub core tools are currently supported. Advanced toolsets such as Actions, Projects, Security, Discussions, and Notifications are not supported.</p></div><h4 id="authentication-3" tabindex="-1"><a class="header-anchor" href="#authentication-3"><span>Authentication</span></a></h4><p>This tool uses a GitHub Personal Access Token. The token is used for all requests on behalf of the agent.</p><p><strong>Steps to get a token:</strong></p><ol><li>Go to GitHub → <strong>Settings</strong> → <strong>Developer settings</strong> → <strong>Personal access tokens</strong>.</li><li>Create a new token (classic or fine-grained).</li><li>Grant the scopes your agent needs — for example <code>repo</code> for full repository access, <code>read:org</code> for organization data.</li><li>Copy the token and paste it into the tool configuration.</li></ol><div class="hint-container tip"><p class="hint-container-title">Fine-grained tokens</p><p>Fine-grained tokens let you limit access to specific repositories and permissions, which is a safer choice for shared agents.</p></div><h3 id="notion" tabindex="-1"><a class="header-anchor" href="#notion"><span>Notion</span></a></h3><p>Search and retrieve pages and content from a Notion workspace. Access is read-only.</p><p>The agent can help with:</p><ul><li><strong>Search</strong> — find pages by title across the workspace</li><li><strong>Pages</strong> — retrieve a page and its properties</li><li><strong>Content</strong> — read the block content of a page</li></ul><div class="hint-container info"><p class="hint-container-title">Shared credentials</p><p>You configure the integration token once. All users of the agent will use it with that Notion workspace data (read-only). Only the agent owner can configure or update this tool.</p></div><h4 id="authentication-4" tabindex="-1"><a class="header-anchor" href="#authentication-4"><span>Authentication</span></a></h4><p>This tool uses a Notion internal integration token.</p><p><strong>Steps to set up:</strong></p><ol><li>Go to <a href="https://www.notion.so/my-integrations" target="_blank" rel="noopener noreferrer">My integrations</a> in Notion and create a new <strong>internal integration</strong>.</li><li>Copy the <strong>Internal Integration Secret</strong> (token).</li><li>In Notion, open each page the agent should access → <strong>⋯</strong> → <strong>Connections</strong> → connect your integration.</li><li>Paste the token into the tool configuration.</li></ol><div class="hint-container tip"><p class="hint-container-title">Page access</p><p>The integration can only see pages you explicitly connect. If search returns nothing, check that the relevant pages are shared with the integration.</p></div><h3 id="youtrack" tabindex="-1"><a class="header-anchor" href="#youtrack"><span>YouTrack</span></a></h3><p>Report issues, log work time, and manage knowledge base articles in JetBrains YouTrack. The agent connects to the YouTrack MCP server built into your instance (requires YouTrack 2025.3 or later).</p><p>The agent can help with:</p><ul><li><strong>Issues</strong> — search using YouTrack query language, create, update, assign, comment on, tag, and link issues</li><li><strong>Time tracking</strong> — log work time directly on issues</li><li><strong>Knowledge Base</strong> — search, read, create, and update articles</li><li><strong>Projects</strong> — find and inspect project configurations and custom field schemas</li><li><strong>Users &amp; groups</strong> — look up users by name or email, list group members</li></ul><h4 id="authentication-5" tabindex="-1"><a class="header-anchor" href="#authentication-5"><span>Authentication</span></a></h4><p>This tool uses a YouTrack permanent token and connects to the YouTrack MCP server built into your instance.</p><p><strong>Steps to set up:</strong></p><ol><li>In YouTrack, click your <strong>avatar</strong> → <strong>Profile</strong> → <strong>Account Security</strong> tab.</li><li>In the <strong>Tokens</strong> section, click <strong>New token</strong>.</li><li>Enter a name and select the <strong>YouTrack</strong> scope, then click <strong>Create token</strong>.</li><li>Copy the token immediately — it is only shown once.</li><li>In the tool configuration, enter: <ul><li><strong>Server URL</strong>: your YouTrack MCP endpoint, e.g. <code>https://your-instance.youtrack.cloud/mcp</code></li><li><strong>Token</strong>: the permanent token you created</li></ul></li></ol><h3 id="practitest" tabindex="-1"><a class="header-anchor" href="#practitest"><span>PractiTest</span></a></h3><p>Manage tests, test sets, and requirements in PractiTest. The agent connects directly to your project data, making it useful for QA workflows that need to bridge AI-generated content with your test management system.</p><p>The agent can help with:</p><ul><li><strong>Tests</strong> — create, read, and update test cases</li><li><strong>Test sets &amp; runs</strong> — manage test sets and track execution results</li><li><strong>Requirements</strong> — read requirements and analyze test coverage</li><li><strong>Coverage analysis</strong> — identify gaps between requirements and existing tests, then create missing tests and link them back to requirements</li></ul><h4 id="authentication-6" tabindex="-1"><a class="header-anchor" href="#authentication-6"><span>Authentication</span></a></h4><p>This tool connects to the PractiTest MCP server.</p><div class="hint-container info"><p class="hint-container-title">Availability</p><p>The PractiTest MCP server is available for Corporate accounts.</p></div><p><strong>Steps to set up:</strong></p><ol><li>In the tool configuration, enter: <ul><li><strong>Server URL</strong>: your PractiTest MCP server URL</li></ul></li></ol><h3 id="redmine" tabindex="-1"><a class="header-anchor" href="#redmine"><span>Redmine</span></a></h3><p>Manage issues, projects, and time tracking in Redmine.</p><div class="hint-container warning"><p class="hint-container-title">Enterprise Edition</p><p>This tool is only available in the Tero Enterprise Edition.</p></div><p>The agent can help with:</p><ul><li><strong>Issues</strong> — create, read, update, and delete issues; add notes; change status and assignee</li><li><strong>Time tracking</strong> — log and review time entries on issues and projects</li><li><strong>Projects</strong> — browse projects and versions</li><li><strong>Search</strong> — find issues across projects using filters</li></ul><h4 id="authentication-7" tabindex="-1"><a class="header-anchor" href="#authentication-7"><span>Authentication</span></a></h4><p>This tool uses a Redmine API key for authentication.</p><div class="hint-container tip"><p class="hint-container-title">Prerequisite</p><p>A Redmine administrator must first enable the REST API under <strong>Administration → Settings → API → Enable REST API</strong>.</p></div><p><strong>Steps to set up:</strong></p><ol><li>In Redmine, click your account name in the top-right → <strong>My account</strong>.</li><li>In the right-hand pane, find your <strong>API access key</strong> (generate one if it doesn&#39;t exist yet).</li><li>In the tool configuration, enter: <ul><li><strong>URL</strong>: your Redmine instance URL, e.g. <code>https://redmine.example.com</code></li><li><strong>API Key</strong>: the key from your Redmine account</li></ul></li></ol><h3 id="mcp" tabindex="-1"><a class="header-anchor" href="#mcp"><span>MCP</span></a></h3><p>Connect to any <a href="https://modelcontextprotocol.io" target="_blank" rel="noopener noreferrer">Model Context Protocol (MCP)</a> server and expose its tools to the agent. This lets you integrate any service that provides an MCP interface without needing a dedicated Tero tool.</p><p>Once connected, the agent automatically discovers and can use all tools exposed by the MCP server — whatever those tools do (querying APIs, managing resources, reading data) becomes available in the agent&#39;s context.</p><h4 id="authentication-8" tabindex="-1"><a class="header-anchor" href="#authentication-8"><span>Authentication</span></a></h4><p>Two authentication modes are supported:</p><p><strong>OAuth</strong> — the agent creator provides the server URL and each user authorizes via the OAuth flow when they first use the tool.</p><p><strong>Bearer Token</strong> — the agent creator provides the server URL and a static bearer token used for all requests.</p><p>Some servers also require custom HTTP headers (for example, a workspace ID or API version header). Use the <strong>Custom headers</strong> field to add any additional headers the server needs.</p><div class="hint-container tip"><p class="hint-container-title">Transport</p><p>The tool supports both SSE (<code>/sse</code> endpoint) and streamable HTTP transports. The correct transport is selected automatically based on the server URL.</p></div><h3 id="sql" tabindex="-1"><a class="header-anchor" href="#sql"><span>SQL</span></a></h3><p>Query databases with natural language. The agent can explore your data and answer questions without writing SQL manually.</p><p>The agent can help with:</p><ul><li><strong>Databases</strong> — list available databases on the server</li><li><strong>Tables</strong> — discover tables and their schemas</li><li><strong>Queries</strong> — run SELECT, INSERT, UPDATE, DELETE, and other SQL statements</li></ul><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>The agent can modify or delete data. To reduce risk, grant database users read-only permissions unless write access is explicitly needed.</p></div><div class="hint-container info"><p class="hint-container-title">Info</p><p>Only Azure SQL Database is currently supported.</p></div><h4 id="authentication-9" tabindex="-1"><a class="header-anchor" href="#authentication-9"><span>Authentication</span></a></h4><p>This tool uses OAuth 2.0. You need to register an app in Azure Active Directory and grant it access to Azure SQL Database.</p><p><strong>Steps to set up:</strong></p><ol><li>Go to the <a href="https://portal.azure.com" target="_blank" rel="noopener noreferrer">Azure portal</a> and open <strong>Microsoft Entra ID</strong> → <strong>App registrations</strong> → <strong>New registration</strong>.</li><li>Give the app a name and set the <strong>Redirect URI</strong> (type: Web) to:<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">{your-tero-url}/tools/sql/oauth-callback</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li>After creating the app, go to <strong>Certificates &amp; secrets</strong> → <strong>New client secret</strong>. Copy the secret value.</li><li>Go to <strong>API permissions</strong> → <strong>Add a permission</strong> → <strong>APIs my organization uses</strong> → search for <strong>Azure SQL Database</strong>.</li><li>Select the <strong>Delegated</strong> permission <code>user_impersonation</code> and click <strong>Add permissions</strong>.</li><li>Copy the <strong>Application (client) ID</strong> and the <strong>Directory (tenant) ID</strong> from the app&#39;s <strong>Overview</strong> page.</li></ol><p>Enter the following fields in the tool configuration:</p><ul><li><strong>Server</strong> (required) — SQL Server fully qualified domain name.</li><li><strong>Tenant ID</strong> (required) — Directory (tenant) ID of the app registration.</li><li><strong>Client ID</strong> (required) — Application (client) ID of the app registration.</li><li><strong>Client secret</strong> (required) — secret created for the app registration.</li><li><strong>Alias</strong> (optional) — see <a href="#multiple-servers">Multiple servers</a> below.</li></ul><p>After saving, each user will be prompted to authorize the connection with their Azure account.</p><h4 id="multiple-servers" tabindex="-1"><a class="header-anchor" href="#multiple-servers"><span>Multiple servers</span></a></h4><p>The tool can be added several times to the same agent, once per server. Each connection has an optional <strong>Alias</strong> that identifies it — if left empty, the server name is used. The alias must be unique among the connections of the agent, and the agent uses it to choose the connection to work with, so give it a meaningful name.</p><p>No matter how many connections are configured, the agent always sees the same tools: when there is more than one connection they just take the alias as an extra input.</p><p>All connections share the same redirect URI, so a single app registration can be reused for every server. Users still need to be provisioned in the databases of each server, and each connection is authorized separately.</p><h4 id="granting-access-to-users" tabindex="-1"><a class="header-anchor" href="#granting-access-to-users"><span>Granting access to users</span></a></h4><p>Because the tool acts on behalf of each user, every user must be provisioned in the databases they need to work with — without this the agent won&#39;t be able to discover or query the data, even if the OAuth authorization succeeds.</p><p>Connect to the target database as the Microsoft Entra admin of the server and create a user from the external provider, then add it to a role with the appropriate permissions:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">USER</span> <span class="token string">&quot;{user-email}&quot;</span> <span class="token keyword">FROM</span> EXTERNAL PROVIDER<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">ALTER</span> ROLE db_datareader <span class="token keyword">ADD</span> MEMBER <span class="token string">&quot;{user-email}&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>db_datareader</code> grants read-only access, which is the recommended setup. If the user needs to modify data, also add them to <code>db_datawriter</code>, or use a broader role such as <code>db_owner</code> for full access:</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token keyword">ALTER</span> ROLE db_owner <span class="token keyword">ADD</span> MEMBER <span class="token string">&quot;{user-email}&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Repeat this in each database the user should be able to query. The user must also be created in <code>master</code>, since the database list is retrieved by querying <code>sys.databases</code> there (on Azure SQL you can only connect to databases where your account is provisioned):</p><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code><span class="line"><span class="token comment">-- connected to master</span></span>
<span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">USER</span> <span class="token string">&quot;{user-email}&quot;</span> <span class="token keyword">FROM</span> EXTERNAL PROVIDER<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Note that <code>sys.databases</code> only returns the databases the account owns unless it has permission to enumerate all databases on the server (e.g. <code>VIEW ANY DATABASE</code>).</p><h2 id="advanced-settings" tabindex="-1"><a class="header-anchor" href="#advanced-settings"><span>Advanced Settings</span></a></h2><p>In the agent editor, <strong>Advanced settings</strong> lets you configure agent mode, the thought process steps limit, and protected configuration.</p><h3 id="agent-mode" tabindex="-1"><a class="header-anchor" href="#agent-mode"><span>Agent mode</span></a></h3><p>Every agent runs in one of two modes: <strong>Basic</strong> or <strong>Advanced</strong>. Basic is the default and works well for most agents.</p><p><strong>Basic</strong> responds quickly and works well for chat, drafting, Q&amp;A, and tasks that need a few tool calls per request.</p>`,96)),s("p",null,[e[27]||(e[27]=s("strong",null,"Advanced",-1)),e[28]||(e[28]=t(" is for complex, multi-step work. It can offload large context to files attached to the chat, summarize long conversations to stay within model limits, and keep better track of subtasks across many steps. It is a better fit when the agent relies heavily on tools or when a single request spans a long-running workflow. Advanced mode is also required to configure ",-1)),a(n,{to:"/guide/tools/subagent.html"},{default:o(()=>[...e[26]||(e[26]=[t("subagents",-1)])]),_:1}),e[29]||(e[29]=t(" — other Tero agents the orchestrator can delegate work to. Advanced mode typically takes longer and uses more budget than Basic.",-1))]),e[42]||(e[42]=r('<h4 id="when-to-use-which" tabindex="-1"><a class="header-anchor" href="#when-to-use-which"><span>When to use which</span></a></h4><p>Use <strong>Basic</strong> if:</p><ul><li>The agent mainly answers questions, drafts text, or brainstorms ideas.</li><li>Each user request usually needs zero to a few tool calls.</li><li>You want the fastest responses and lowest cost.</li><li>You are creating a new agent — start here.</li></ul><p>Use <strong>Advanced</strong> if:</p><ul><li>A request often requires many tool calls in sequence (e.g., search, read, compare, update, verify).</li><li>Users attach large documents and the agent must refer back to them across multiple turns.</li><li>Chats run long and the agent loses earlier context or truncates attachments in Basic mode.</li><li>You want the agent to delegate parts of a request to other specialized agents.</li></ul><p>When in doubt, keep <strong>Basic</strong>. Switch to <strong>Advanced</strong> only when you see a clear need — for example, lost file context or workflows that stall in Basic mode.</p><div class="hint-container tip"><p class="hint-container-title">Start with Basic</p><p>Create and tune new agents in Basic mode first. Optimize the system prompt, tools, and model before switching to Advanced. Advanced mode solves different problems — it is not a substitute for clear instructions.</p></div><div class="hint-container tip"><p class="hint-container-title">Files in Advanced mode</p><p>In Advanced mode, text attachments are kept in a per-chat workspace the agent can read across turns, instead of repeating the full content every time.</p></div><div class="hint-container warning"><p class="hint-container-title">Switching to Basic</p><p>Switching back to Basic removes any configured subagents. The agent will no longer be able to delegate work.</p></div><h3 id="thought-process-steps-limit" tabindex="-1"><a class="header-anchor" href="#thought-process-steps-limit"><span>Thought process steps limit</span></a></h3><p>This setting caps how many steps the agent can take while answering a single request — each model turn or tool call counts toward the limit. It prevents runaway loops and unnecessary budget spend.</p><p>The default is <strong>20</strong> steps. You can raise it to <strong>40</strong>, <strong>60</strong>, <strong>80</strong>, or <strong>100</strong> if legitimate workflows need more room.</p>',12)),s("div",v,[e[33]||(e[33]=s("p",{class:"hint-container-title"},"Budget and latency",-1)),s("p",null,[e[31]||(e[31]=t("Higher limits increase response time and budget usage. Before raising the limit, review the ",-1)),a(n,{to:"/guide/chat.html#thought-process"},{default:o(()=>[...e[30]||(e[30]=[t("Thought Process",-1)])]),_:1}),e[32]||(e[32]=t(" for failed requests and tighten the system prompt or reduce tools so the agent needs fewer steps.",-1))])]),e[43]||(e[43]=r('<h3 id="protected-configuration" tabindex="-1"><a class="header-anchor" href="#protected-configuration"><span>Protected configuration</span></a></h3><p><strong>Protected configuration</strong> is available only to <strong>global owners</strong> of the Tero instance. When enabled, other users cannot view, clone, or modify the agent’s configuration — including its system prompt, model, tools, and advanced settings. They can still chat with the agent normally.</p><p>Use this when you publish an agent widely but want to keep its setup private — for example, agents with sensitive instructions, proprietary workflows, or carefully tuned behavior you do not want copied or edited.</p><div class="hint-container warning"><p class="hint-container-title">Use sparingly</p><p>Avoid unless truly necessary. Protected agents can&#39;t be learned from, cloned, or improved by others — working against Tero&#39;s spirit of collaboration and sharing.</p></div><h2 id="tests" tabindex="-1"><a class="header-anchor" href="#tests"><span>Tests</span></a></h2><p><img src="'+h+'" alt="Agent Tests"></p><p>Tero focuses on software quality, and quality requires tests. Add tests to ensure your agents behave as intended.</p><p>Tests let creators and editors experiment safely. Define a test suite for your agent by specifying user inputs and example expected outputs. Then you can change models, prompts, tools, etc., and verify, by running the test suite, that your core use cases still work.</p><h2 id="publish" tabindex="-1"><a class="header-anchor" href="#publish"><span>Publish</span></a></h2><p>When your agent starts being useful to you, share it with your team so others can benefit too!</p><p>You can share it with any private team (only your teammates can use it), or with the Global team (all users in your Tero instance can discover and use it).</p><p>When you share an agent with a team, the team leaders can edit the agent if they need to improve it. You’ll still be able to edit it, and you’ll remain listed as the author.</p><h2 id="export-import" tabindex="-1"><a class="header-anchor" href="#export-import"><span>Export &amp; Import</span></a></h2><p>You can move agents (or their updates) between Tero environments by exporting and importing them.</p><p>Furthermore, you can import any agents contributed by the community from the <a href="https://github.com/abstracta/tero-agents" target="_blank" rel="noopener noreferrer">public repository of agents</a>.</p><h2 id="persistent-memory" tabindex="-1"><a class="header-anchor" href="#persistent-memory"><span>Persistent memory</span></a></h2><p>Persistent memory lets an <strong>Advanced</strong> agent remember useful information across chats. Each memory belongs to a specific user and agent: it is shared across that user&#39;s chats with the same agent and isolated from other users and agents. Basic agents do not use persistent memory.</p><p>For new agents, persistent memory is off by default. To enable it, switch the agent to <strong>Advanced</strong> mode and turn on <strong>Persistent memory</strong> in its advanced settings.</p><p>When persistent memory is off, the agent cannot read or update its memory. Turning it back on restores access to the existing memory. Switching the agent temporarily to Basic mode also leaves its memory intact, and deleting a chat does not delete persistent memory.</p><p>Manage remembered information by asking the agent to remember or forget it. Do not store passwords, access tokens, or other secrets in agent memory.</p><p>Be part of the Tero community: contribute your agents so everyone benefits! Export your agent and submit a Pull Request to the repository.</p>',21))])}const k=i(u,[["render",b]]),T=JSON.parse('{"path":"/guide/agents.html","title":"Create Agents","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"Clone","slug":"clone","link":"#clone","children":[]},{"level":2,"title":"Basic Info","slug":"basic-info","link":"#basic-info","children":[]},{"level":2,"title":"Model","slug":"model","link":"#model","children":[{"level":3,"title":"Temperature","slug":"temperature","link":"#temperature","children":[]},{"level":3,"title":"Reasoning Level","slug":"reasoning-level","link":"#reasoning-level","children":[]}]},{"level":2,"title":"Instructions","slug":"instructions","link":"#instructions","children":[]},{"level":2,"title":"Conversation Starters","slug":"conversation-starters","link":"#conversation-starters","children":[]},{"level":2,"title":"Tools","slug":"tools","link":"#tools","children":[{"level":3,"title":"Docs","slug":"docs","link":"#docs","children":[]},{"level":3,"title":"Web","slug":"web","link":"#web","children":[]},{"level":3,"title":"Browser","slug":"browser","link":"#browser","children":[]},{"level":3,"title":"Subagent","slug":"subagent","link":"#subagent","children":[]},{"level":3,"title":"Jira","slug":"jira","link":"#jira","children":[]},{"level":3,"title":"Azure DevOps","slug":"azure-devops","link":"#azure-devops","children":[]},{"level":3,"title":"Zephyr","slug":"zephyr","link":"#zephyr","children":[]},{"level":3,"title":"GitHub","slug":"github","link":"#github","children":[]},{"level":3,"title":"Notion","slug":"notion","link":"#notion","children":[]},{"level":3,"title":"YouTrack","slug":"youtrack","link":"#youtrack","children":[]},{"level":3,"title":"PractiTest","slug":"practitest","link":"#practitest","children":[]},{"level":3,"title":"Redmine","slug":"redmine","link":"#redmine","children":[]},{"level":3,"title":"MCP","slug":"mcp","link":"#mcp","children":[]},{"level":3,"title":"SQL","slug":"sql","link":"#sql","children":[]}]},{"level":2,"title":"Advanced Settings","slug":"advanced-settings","link":"#advanced-settings","children":[{"level":3,"title":"Agent mode","slug":"agent-mode","link":"#agent-mode","children":[]},{"level":3,"title":"Thought process steps limit","slug":"thought-process-steps-limit","link":"#thought-process-steps-limit","children":[]},{"level":3,"title":"Protected configuration","slug":"protected-configuration","link":"#protected-configuration","children":[]}]},{"level":2,"title":"Tests","slug":"tests","link":"#tests","children":[]},{"level":2,"title":"Publish","slug":"publish","link":"#publish","children":[]},{"level":2,"title":"Export & Import","slug":"export-import","link":"#export-import","children":[]},{"level":2,"title":"Persistent memory","slug":"persistent-memory","link":"#persistent-memory","children":[]}],"git":{"contributors":[{"name":"luisvillegasbf23","username":"luisvillegasbf23","email":"89048385+luisvillegasbf23@users.noreply.github.com","commits":1,"url":"https://github.com/luisvillegasbf23"}],"changelog":[{"hash":"52ab7056e6b14b1ff4e18ff5fb4073f1944e6a28","time":1791993231000,"email":"89048385+luisvillegasbf23@users.noreply.github.com","author":"Luis Villegas","message":"Merge pull request #47 from abstracta/sync-ee-release-2610091902"}]},"filePathRelative":"guide/agents.md"}');export{k as comp,T as data};
